function bubble(title, body, btnLabel, uri, extra) {
  const bodyContents = [
    { type: 'text', text: title, weight: 'bold', size: 'md', wrap: true, color: '#1F2A22' },
    { type: 'text', text: body, size: 'sm', color: '#6B7A6E', wrap: true }
  ];
  if (extra) bodyContents.push({ type: 'text', text: extra, size: 'xs', color: '#8A9388', wrap: true, margin: 'md' });
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: '#3E5C46', paddingAll: '16px',
      contents: [ { type: 'text', text: 'LLOOP', color: '#FFFFFF', weight: 'bold', size: 'sm' } ] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '20px', contents: bodyContents },
    footer: { type: 'box', layout: 'vertical', paddingAll: '16px',
      contents: [ { type: 'button', style: 'primary', color: '#3E5C46', height: 'sm',
        action: { type: 'uri', label: btnLabel, uri: uri } } ] }
  };
}

// กรองเฉพาะงานที่ "ยังไม่ทัก" (pinged_at เป็น null) แล้วสรุปเป็นข้อความเดียวส่งหาสไตลิสต์/เจ้าของร้าน
// Human-in-the-loop โดยตั้งใจ: workflow นี้แค่แจ้งทีมงาน — สไตลิสต์เป็นคนจัดลุคแล้วกด "ทักแล้ว"
// ใน today.html เอง (ห้าม auto-mark pinged จากตรงนี้)
const events = $input.all().map(i => i.json).filter(e => !e.pinged_at);
if (events.length === 0) { return []; } // ไม่มีงานค้างทัก → จบเงียบ ๆ ไม่ส่ง LINE

// จัดกลุ่มตามวันที่ให้อ่านง่าย
const byDate = {};
for (const e of events) { (byDate[e.date] = byDate[e.date] || []).push(e); }
const lines = Object.keys(byDate).sort().map(d => {
  const list = byDate[d];
  const occ = list.map(e => e.occasion + (e.venue ? ' @' + e.venue : '')).join(', ');
  return '• ' + d + ' — ' + list.length + ' งาน: ' + occ;
});
const summary = lines.join('\n').slice(0, 1500);

const to = $env.STYLIST_LINE_UID;
if (!to) { throw new Error('ยังไม่ได้ตั้ง env STYLIST_LINE_UID (LINE userId ของสไตลิสต์/เจ้าของร้าน)'); }

const title = 'มีงานลูกค้าใกล้ถึง ' + events.length + ' งานค่ะ';
const bodyText = 'เปิด today.html เพื่อจัดลุคและกด "ทักแล้ว" นะคะ';
const contents = bubble(title, bodyText, 'เปิดคิวสไตลิสต์ (today.html)',
                        'https://wearlloop-dotcom.github.io/today.html', summary);
return [{ json: {
  total: events.length,
  lineBody: { to, messages: [{ type: 'flex',
    altText: 'มีงานลูกค้าใกล้ถึง ' + events.length + ' งาน — เปิด today.html เพื่อจัดลุคและกดทักแล้ว',
    contents }] }
} }];
